265	+// The inner report ends before sideband progress and the process itself do.
266	+// Enough trailing output to fill a pipe makes an early close break the writer.
267	+func lateReceivePackResponse() string {
268	+	report := FormatPktLine("unpack ok\n") + FormatPktLine("ng refs/heads/main stale info\n") + "0000"
269	+	progress := strings.Repeat(FormatPktLine("\x02"+strings.Repeat("hook output\n", 2048)), 64)
270	+	return FormatPktLine("\x01"+report) + progress + FormatPktLine("\x02hook finished\n") + "0000"
271	+}
