154	// Enough trailing output to fill a pipe makes an early close break the writer.
155	func lateReceivePackResponse() string {
156		report := FormatPktLine("unpack ok\n") + FormatPktLine("ng refs/heads/main stale info\n") + "0000"
157		progress := strings.Repeat(FormatPktLine("\x02"+strings.Repeat("hook output\n", 2048)), 64)
158		return FormatPktLine("\x01"+report) + progress + FormatPktLine("\x02hook finished\n") + "0000"
159	}
