161	func TestPusherDrainsReceivePackBeforeConvergence(t *testing.T) {
162		for _, kind := range []string{"ssh", "helper"} {
163			t.Run(kind, func(t *testing.T) {
164				var conn Conn
165				if kind == "helper" {
166					conn = fakeHelperConn(t, "late-rejection")
167				} else {
168					dir := t.TempDir()
169					response := filepath.Join(dir, "response")
170					if err := os.WriteFile(response, []byte(lateReceivePackResponse()), 0o600); err != nil {
171						t.Fatal(err)
172					}
173					advertisement := filepath.Join(dir, "advertisement")
174					if err := os.WriteFile(advertisement, []byte(fakeV0Advertisement), 0o600); err != nil {
175						t.Fatal(err)
176					}
177					script := filepath.Join(dir, "ssh")
178					writeShellStub(t, script, "cat "+shellQuote(advertisement)+"\ncat >/dev/null\ncat "+shellQuote(response))
179					conn = newSSHTestConn(t, "ssh://example.com/repo.git", script)
180				}
181				var progress bytes.Buffer
182				conn.SetProgressWriter(&progress)
183				adv := &packp.AdvRefs{}
184				adv.Capabilities.Set(capability.ReportStatus)
185				adv.Capabilities.Set(capability.Sideband64k)
186				p := NewPusher(conn, adv, true)
187				wanted := plumbing.NewHash("1111111111111111111111111111111111111111")
188				read := false
189				p.TargetRefsNow = func(context.Context) (map[plumbing.ReferenceName]plumbing.Hash, error) {
190					read = true
191					if !strings.Contains(progress.String(), "hook finished") {
192						t.Error("verification started before hook output drained")
193						return nil, errors.New("verification started before hook output drained")
194					}
195					return map[plumbing.ReferenceName]plumbing.Hash{"refs/heads/main": wanted}, nil
196				}
197				ctx, cancel := context.WithTimeout(t.Context(), 10*time.Second)
198				defer cancel()
199				if err := p.PushPack(ctx, []PushCommand{{Name: "refs/heads/main", New: wanted}}, io.NopCloser(bytes.NewReader(emptyPack(adv)))); err != nil {
200					t.Fatal(err)
201				}
202				if !read {
203					t.Fatal("convergence was not checked")
204				}
205				if outcome, _ := p.LastOutcome("refs/heads/main"); outcome != RefOutcomeAlreadyCurrent {
206					t.Fatalf("outcome = %v", outcome)
207				}
208			})
209		}
