212	type receivePackTestConn struct {
213		stubConn
214	
215		response io.ReadCloser
216		progress io.Writer
217	}
218	
219	func (c *receivePackTestConn) PostRPCStreamBody(context.Context, string, io.Reader, bool, string) (io.ReadCloser, error) {
220		return c.response, nil
221	}
222	
223	func (c *receivePackTestConn) ProgressWriter() io.Writer { return c.progress }
224	
225	// failingReceivePackResponse serves report, then fails in phase ("read" or "close").
226	func failingReceivePackResponse(report, phase string, failure error) *countingCloser {
227		if phase == "close" {
228			return &countingCloser{Reader: strings.NewReader(report), closeErr: failure}
229		}
230		return &countingCloser{Reader: io.MultiReader(strings.NewReader(report), iotest.ErrReader(failure))}
231	}
232	
233	func TestPusherPreservesReceivePackCompletionErrors(t *testing.T) {
234		for _, phase := range []string{"read", "close"} {
235			t.Run(phase, func(t *testing.T) {
236				failure := fmt.Errorf("target %s failure", phase)
237				report := FormatPktLine("unpack ok\n") + FormatPktLine("ng refs/heads/main stale info\n") + "0000"
238				response := failingReceivePackResponse(report, phase, failure)
239				adv := &packp.AdvRefs{}
240				adv.Capabilities.Set(capability.ReportStatus)
241				p := NewPusher(&receivePackTestConn{response: response}, adv, false)
242				p.TargetRefsNow = func(context.Context) (map[plumbing.ReferenceName]plumbing.Hash, error) {
243					t.Error("must not verify after transport failure")
244					return nil, failure
245				}
246				err := p.PushCommands(t.Context(), []PushCommand{{Name: "refs/heads/main", New: plumbing.NewHash("1111111111111111111111111111111111111111")}})
247				if !errors.Is(err, failure) || !errors.Is(err, ErrTargetRefMoved) {
248					t.Fatalf("lost transport or ref rejection: %v", err)
249				}
250				if !strings.Contains(err.Error(), "target receive-pack") || strings.Contains(err.Error(), "close pack reader") {
251					t.Fatalf("misleading error: %v", err)
252				}
253				if response.closes != 1 {
254					t.Fatalf("closed %d times", response.closes)
255				}
256			})
257		}
258	}
