260	// receive-pack reports only after committing, so a transport failure after an
261	// all-accepted report must not fail the push or lose the recorded outcomes.
262	func TestPusherAcceptedReportSurvivesCompletionErrors(t *testing.T) {
263		main := plumbing.ReferenceName("refs/heads/main")
264		other := plumbing.ReferenceName("refs/heads/other")
265		wanted := plumbing.NewHash("1111111111111111111111111111111111111111")
266		for _, tc := range []struct {
267			name      string
268			phase     string
269			rejectOne bool
270		}{
271			{name: "read_after_accept", phase: "read"},
272			{name: "close_after_accept", phase: "close"},
273			{name: "close_after_partial_reject", phase: "close", rejectOne: true},
274		} {
275			t.Run(tc.name, func(t *testing.T) {
276				failure := fmt.Errorf("target %s failure", tc.phase)
277				otherStatus := "ok refs/heads/other\n"
278				if tc.rejectOne {
279					otherStatus = "ng refs/heads/other stale info\n"
280				}
281				report := FormatPktLine("unpack ok\n") + FormatPktLine("ok refs/heads/main\n") + FormatPktLine(otherStatus) + "0000"
282				response := failingReceivePackResponse(report, tc.phase, failure)
283				var progress bytes.Buffer
284				adv := &packp.AdvRefs{}
285				adv.Capabilities.Set(capability.ReportStatus)
286				p := NewPusher(&receivePackTestConn{response: response, progress: &progress}, adv, false)
287				p.TargetRefsNow = func(context.Context) (map[plumbing.ReferenceName]plumbing.Hash, error) {
288					t.Error("must not verify after transport failure")
289					return nil, failure
290				}
291				err := p.PushCommands(t.Context(), []PushCommand{{Name: main, New: wanted}, {Name: other, New: wanted}})
292				if outcome, _ := p.LastOutcome(main); outcome != RefOutcomeApplied {
293					t.Errorf("accepted ref outcome = %v, want applied", outcome)
294				}
295				if tc.rejectOne {
296					if !errors.Is(err, failure) || !errors.Is(err, ErrTargetRefMoved) {
297						t.Fatalf("lost transport or ref rejection: %v", err)
298					}
299					return
300				}
301				if err != nil {
302					t.Fatalf("accepted push failed: %v", err)
303				}
304				if outcome, _ := p.LastOutcome(other); outcome != RefOutcomeApplied {
305					t.Errorf("accepted ref outcome = %v, want applied", outcome)
306				}
307				if !strings.Contains(progress.String(), "did not finish cleanly") || !strings.Contains(progress.String(), failure.Error()) {
308					t.Errorf("transport failure not surfaced: %q", progress.String())
309				}
310			})
311		}
312	}
